ST.xhtml:
NamedB();
NamedA();
Whitespace();
DisabledCase();
Duplicate();
ConflictingShape();
_found := GetCanonicalRecord(Index := 6, Record => _shape);
ShapePreserved := _found AND NOT _shape.IsOrdered AND (_shape.OrderNumber = 0) AND (_shape.CanonicalName = 'Shape') AND (_shape.State = E_CoUnitTestState.PASSED);

TEST('NamedB');
IF NOT IS_TEST_FINISHED('NamedB') THEN
	// Remain open until NamedA finishes this known target.
END_IF

TEST('NamedA');
IF NOT IS_TEST_FINISHED('NamedA') THEN
	AssertTrue(Condition := TRUE, Message := 'before-B');
	TEST_FINISHED_NAMED('NamedB');
	AssertTrue(Condition := TRUE, Message := 'after-B');
	TEST_FINISHED();
END_IF

TEST('  Trimmed  ');
IF NOT IS_TEST_FINISHED('Trimmed') THEN
	TEST_FINISHED();
END_IF

TEST('Duplicate');
AssertTrue(Condition := TRUE, Message := 'first-definition');
TEST_FINISHED();
TEST('Duplicate');
AssertTrue(Condition := FALSE, Message := 'must-be-suppressed');
TEST_FINISHED();

TEST('Shape');
AssertTrue(Condition := TRUE, Message := 'original-shape');
TEST_FINISHED();
TEST_ORDERED('Shape');
AssertTrue(Condition := FALSE, Message := 'conflicting-shape-must-be-suppressed');
TEST_FINISHED();

