FUNCTION_BLOCK FB_QualificationNames EXTENDS FB_TestSuite
VAR_OUTPUT
	ShapePreserved : BOOL;
END_VAR
VAR
	_shape : ST_CoUnitTestRecord;
	_found : BOOL;
END_VAR

PROGRAM PRG_Qualification
VAR_OUTPUT
	Done : BOOL;
	OraclePass : BOOL;
	FailedCheck : UDINT;
	SnapshotBytes : UDINT;
END_VAR
VAR
	_suite1 : FB_QualificationNames;
	_snapshot : REFERENCE TO ST_CoUnitRunSnapshot;

END_VAR
